-- =====================================================================
-- ERP NOX · 021_carga_categorias.sql
-- Plano de categorias financeiras aprovado em 14/10/2026 (Plano_Categorias_Financeiras_NOX.xlsx):
-- 51 grupos/subgrupos + 272 categorias (266 do Tiny com o ID do Tiny + 6 receitas novas).
-- Só inclui o que não existe (pelo código). Tudo editável depois na tela Categorias financeiras.
-- =====================================================================
on conflict (codigo) do nothing;

-- Liga cada categoria ao seu grupo pai pelo código (2.01.003 -> 2.01 -> 2)
update public.categorias_financeiras c set pai_id = p.id
  from public.categorias_financeiras p
 where c.pai_id is null and position('.' in c.codigo) > 0
   and p.codigo = regexp_replace(c.codigo, '\.[0-9]+$', '');
